#include <list>

int main() {
    std::list<int> l;

    // l.capacity(); // ERROR: capacity() is not a member of std::list
    // l.reserve(100); // ERROR: reserve() is not a member of std::list

    // Memory is allocated incrementally as elements are added.
    for (int i = 0; i < 5; ++i) {
        l.push_back(i);
    }

    // The memory of the first element remains stable and separate
    // from the memory of the last element.
}
